--
-- Table structure for table `student_profile`
--

CREATE TABLE `student_profile` (
  `student_id` varchar(20) NOT NULL,
  `summary` text DEFAULT NULL,
  `skills` text DEFAULT NULL,
  `social_links` text DEFAULT NULL,
